window.docContents[53].resolve({"/Sub/#Type-Systems--Sub___-Subtyping--Properties--Exercises--Exercise___-Adding-Products":{"contents":"\n\n\n\nAnother great hard exercise (probably just for the advanced\ntrack) is to get them to figure out how to add sums and case.  Note\nthat this gets into thinking about joins, if you extend it to the\nalgorithmic version.\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Properties\u0009Exercises","header":"8.3.9.1. Exercise: Adding Products","id":"/Sub/#Type-Systems--Sub___-Subtyping--Properties--Exercises--Exercise___-Adding-Products"}});